/* ==================================================================
 * 修正：悬空部门引用
 * ------------------------------------------------------------------
 * 背景：
 *   `manage.py init -y` 创建的超管初始部门 key='dvadmin'，而本 seed 的
 *   部门集合是 devops / develop / ops / test（不含 dvadmin）。Users.dept 是
 *   带真实外键约束的 PROTECT 字段（见 dvadmin/system/models.py），
 *   上文的 `DELETE FROM dvadmin_system_dept`（配合 FOREIGN_KEY_CHECKS=0）
 *   执行后，users.dept_id 会指向一个已不存在的部门 —— Django 读取该用户时
 *   抛 Dept.DoesNotExist，表现为登录后部分页面 500。
 * 处理：
 *   把悬空的 dept_id 统一重挂到 devops 部门；若 devops 不存在则置 NULL
 *   （dept 允许为空）。本语句对 users 表为空的情况同样安全（0 行受影响）。
 * ================================================================== */
UPDATE `dvadmin_system_users`
SET `dept_id` = (SELECT `id` FROM `dvadmin_system_dept` WHERE `key` = 'devops' LIMIT 1)
WHERE `dept_id` IS NOT NULL
  AND `dept_id` NOT IN (SELECT `id` FROM `dvadmin_system_dept`);

SET FOREIGN_KEY_CHECKS=1;
